15	// fakeCrow with two versions of moduleA. v1 has main.tf; v2 has main.tf
16	// (modified) and a new variables.tf.
17	func fakeCrowTwoVersions(t *testing.T) *httptest.Server {
18		t.Helper()
19		mkTgz := func(files map[string]string) []byte {
20			var buf bytes.Buffer
21			gz := gzip.NewWriter(&buf)
22			tw := tar.NewWriter(gz)
23			for n, b := range files {
24				_ = tw.WriteHeader(&tar.Header{Name: n, Mode: 0o644, Size: int64(len(b)), Typeflag: tar.TypeReg})
25				_, _ = tw.Write([]byte(b))
26			}
27			_ = tw.Close()
28			_ = gz.Close()
29			return buf.Bytes()
30		}
31		v1 := mkTgz(map[string]string{"main.tf": "resource \"aws_s3_bucket\" \"alpha\" {}\n"})
32		v2 := mkTgz(map[string]string{
33			"main.tf":      "resource \"aws_s3_bucket\" \"beta\" {}\n",
34			"variables.tf": "variable \"name\" { type = string }\n",
35		})
36	
37		mux := http.NewServeMux()
38		blob := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
39			switch r.URL.Path {
40			case "/blob/1.0.0":
41				_, _ = w.Write(v1)
42			case "/blob/1.1.0":
43				_, _ = w.Write(v2)
44			default:
45				http.NotFound(w, r)
46			}
47		}))
48		t.Cleanup(blob.Close)
49		mux.HandleFunc("/v1/modules/iac/comply/aws/", func(w http.ResponseWriter, r *http.Request) {
50			parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/v1/modules/iac/comply/aws/"), "/")
51			if len(parts) != 2 || parts[1] != "download" {
52				http.NotFound(w, r)
53				return
54			}
55			w.Header().Set("X-Terraform-Get", blob.URL+"/blob/"+parts[0])
56			w.WriteHeader(http.StatusNoContent)
57		})
58		srv := httptest.NewServer(mux)
59		t.Cleanup(srv.Close)
60		return srv
61	}
